    reg [15:0] C_temp; // Changed wire to reg to avoid circular logic
    assign P = A ^ B; // Propagate
    assign G = A & B; // Generate
    always @(*) begin
        C_temp[0] = Cin;
        C_temp[1] = G[0] | (P[0] & C_temp[0]);
        C_temp[2] = G[1] | (P[1] & C_temp[1]);
        C_temp[3] = G[2] | (P[2] & C_temp[2]);
        C_temp[4] = G[3] | (P[3] & C_temp[3]);
        C_temp[5] = G[4] | (P[4] & C_temp[4]);
        C_temp[6] = G[5] | (P[5] & C_temp[5]);
        C_temp[7] = G[6] | (P[6] & C_temp[6]);
        C_temp[8] = G[7] | (P[7] & C_temp[7]);
        C_temp[9] = G[8] | (P[8] & C_temp[8]);
        C_temp[10] = G[9] | (P[9] & C_temp[9]);
        C_temp[11] = G[10] | (P[10] & C_temp[10]);
        C_temp[12] = G[11] | (P[11] & C_temp[11]);
        C_temp[13] = G[12] | (P[12] & C_temp[12]);
        C_temp[14] = G[13] | (P[13] & C_temp[13]);
        C_temp[15] = G[14] | (P[14] & C_temp[14]);
